import screenfull from "screenfull";

export const useFullscreen = () => {
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    if (screenfull.isEnabled) {
      const handleFullscreenChange = () => {
        setIsFullscreen(screenfull.isFullscreen);
      };

      screenfull.on("change", handleFullscreenChange);
      return () => {
        screenfull.off("change", handleFullscreenChange);
      };
    }
  }, []);

  const toggleFullscreen = () => {
    if (screenfull.isEnabled) {
      screenfull.toggle();
    }
  };

  return {
    isFullscreen,
    toggleFullscreen,
  };
};
/* eslint-disable promise/prefer-await-to-then */

const methodMap = [
	[
		'requestFullscreen',
		'exitFullscreen',
		'fullscreenElement',
		'fullscreenEnabled',
		'fullscreenchange',
		'fullscreenerror',
	],
	// New WebKit
	[
		'webkitRequestFullscreen',
		'webkitExitFullscreen',
		'webkitFullscreenElement',
		'webkitFullscreenEnabled',
		'webkitfullscreenchange',
		'webkitfullscreenerror',

	],
	// Old WebKit
	[
		'webkitRequestFullScreen',
		'webkitCancelFullScreen',
		'webkitCurrentFullScreenElement',
		'webkitCancelFullScreen',
		'webkitfullscreenchange',
		'webkitfullscreenerror',

	],
	[
		'mozRequestFullScreen',
		'mozCancelFullScreen',
		'mozFullScreenElement',
		'mozFullScreenEnabled',
		'mozfullscreenchange',
		'mozfullscreenerror',
	],
	[
		'msRequestFullscreen',
		'msExitFullscreen',
		'msFullscreenElement',
		'msFullscreenEnabled',
		'MSFullscreenChange',
		'MSFullscreenError',
	],
];

const nativeAPI = (() => {
	if (typeof document === 'undefined') {
		return false;
	}

	const unprefixedMethods = methodMap[0];
	const returnValue = {};

	for (const methodList of methodMap) {
		const exitFullscreenMethod = methodList?.[1];
		if (exitFullscreenMethod in document) {
			for (const [index, method] of methodList.entries()) {
				returnValue[unprefixedMethods[index]] = method;
			}

			return returnValue;
		}
	}

	return false;
})();

const eventNameMap = {
	change: nativeAPI.fullscreenchange,
	error: nativeAPI.fullscreenerror,
};

// eslint-disable-next-line import/no-mutable-exports
let screenfull = {
	// eslint-disable-next-line default-param-last
	request(element = document.documentElement, options) {
		return new Promise((resolve, reject) => {
			const onFullScreenEntered = () => {
				screenfull.off('change', onFullScreenEntered);
				resolve();
			};

			screenfull.on('change', onFullScreenEntered);

			const returnPromise = element[nativeAPI.requestFullscreen](options);

			if (returnPromise instanceof Promise) {
				returnPromise.then(onFullScreenEntered).catch(reject);
			}
		});
	},
	exit() {
		return new Promise((resolve, reject) => {
			if (!screenfull.isFullscreen) {
				resolve();
				return;
			}

			const onFullScreenExit = () => {
				screenfull.off('change', onFullScreenExit);
				resolve();
			};

			screenfull.on('change', onFullScreenExit);

			const returnPromise = document[nativeAPI.exitFullscreen]();

			if (returnPromise instanceof Promise) {
				returnPromise.then(onFullScreenExit).catch(reject);
			}
		});
	},
	toggle(element, options) {
		return screenfull.isFullscreen ? screenfull.exit() : screenfull.request(element, options);
	},
	onchange(callback) {
		screenfull.on('change', callback);
	},
	onerror(callback) {
		screenfull.on('error', callback);
	},
	on(event, callback) {
		const eventName = eventNameMap[event];
		if (eventName) {
			document.addEventListener(eventName, callback, false);
		}
	},
	off(event, callback) {
		const eventName = eventNameMap[event];
		if (eventName) {
			document.removeEventListener(eventName, callback, false);
		}
	},
	raw: nativeAPI,
};

Object.defineProperties(screenfull, {
	isFullscreen: {
		get: () => Boolean(document[nativeAPI.fullscreenElement]),
	},
	element: {
		enumerable: true,
		get: () => document[nativeAPI.fullscreenElement] ?? undefined,
	},
	isEnabled: {
		enumerable: true,
		// Coerce to boolean in case of old WebKit.
		get: () => Boolean(document[nativeAPI.fullscreenEnabled]),
	},
});

if (!nativeAPI) {
	screenfull = {isEnabled: false};
}

export default screenfull;
export interface InspectorState {
  rect: DOMRect | null;
  className: string;
}

export const areRectsEqual = (rect1: DOMRect | null, rect2: DOMRect | null): boolean => {
  if (!rect1 || !rect2) return rect1 === rect2;

  return (
    rect1.top === rect2.top &&
    rect1.left === rect2.left &&
    rect1.width === rect2.width &&
    rect1.height === rect2.height
  );
};

export const areInspectorStatesEqual = (
  state1: InspectorState,
  state2: InspectorState
): boolean => {
  return areRectsEqual(state1.rect, state2.rect) && state1.className === state2.className;
};

export const createInspectorState = (rect: DOMRect, matches: string[]): InspectorState => ({
  rect,
  className: matches.join(" "),
});

export const getEmptyInspectorState = (): InspectorState => ({
  rect: null,
  className: "",
});
import { useState, useRef, useCallback } from "react";
import {
  InspectorState,
  areInspectorStatesEqual,
  createInspectorState,
  getEmptyInspectorState,
} from "../../lib/inspector/inspector-state-utils";

export const useInspectorState = () => {
  const [inspector, setInspector] = useState<InspectorState>(getEmptyInspectorState());
  const [inspectorEnabled, setInspectorEnabled] = useState(false);
  const lastElementRef = useRef<HTMLElement | null>(null);
  const isOverlayHiddenRef = useRef<boolean>(false);

  const updateInspectorState = useCallback((rect: DOMRect, matches: string[]) => {
    setInspector((prev: InspectorState) => {
      const newState = createInspectorState(rect, matches);

      if (areInspectorStatesEqual(prev, newState)) {
        return prev;
      }

      isOverlayHiddenRef.current = false;
      return newState;
    });
  }, []);

  const clearInspectorState = useCallback(() => {
    if (lastElementRef.current || !isOverlayHiddenRef.current) {
      lastElementRef.current = null;
      isOverlayHiddenRef.current = true;
      setInspector(getEmptyInspectorState());
    }
  }, []);

  const toggleInspector = useCallback((onToggleOff?: () => void) => {
    setInspectorEnabled((prev) => {
      if (prev) {
        lastElementRef.current = null;
        isOverlayHiddenRef.current = true;
        setInspector(getEmptyInspectorState());
        onToggleOff?.();
      } else {
        isOverlayHiddenRef.current = false;
      }
      return !prev;
    });
  }, []);

  return {
    inspector,
    inspectorEnabled,
    lastElementRef,
    isOverlayHiddenRef,
    updateInspectorState,
    clearInspectorState,
    toggleInspector,
  };
};
